"use client";

import "./living-type-font.css";

import {
  Component,
  Suspense,
  lazy,
  useEffect,
  useMemo,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import type { MeshGradientProps } from "@paper-design/shaders-react";
import styles from "./living-type.module.css";
import {
  DEFAULT_LIVING_TYPE_RECIPE,
  DEFAULT_PRESET_ID,
  LIVING_TYPE_TEXT_PATTERN,
  createLivingTypeRecipe,
  hexToRgbTriplet,
  parseLivingTypeRecipe,
  type LivingTypeColors,
  type LivingTypeMaterial,
  type LivingTypePresetId,
  type LivingTypeRecipe,
  type LivingTypeRecipeOptions,
  type ReducedMotionPreference,
} from "./living-type-recipe";
import { useLivingTypeFont, useLivingTypeMask } from "./living-type-mask";

/**
 * The Paper Shaders package is lazy-loaded so the consumer's initial route does
 * not pay for the renderer before the wordmark is on screen. This is a plain
 * dynamic import: it is not a Next-specific API and works in Vite.
 */
const LazyMeshGradient = lazy(() =>
  import("@paper-design/shaders-react").then((module) => ({ default: module.MeshGradient })),
);

export interface LivingTypeProps {
  /** A complete recipe. When supplied, it takes precedence over convenience props. */
  recipe?: LivingTypeRecipe;
  text?: string;
  preset?: LivingTypePresetId;
  paused?: boolean;
  reducedMotion?: ReducedMotionPreference;
  weight?: number;
  fit?: number;
  tracking?: number;
  aspect?: number;
  colors?: LivingTypeColors;
  material?: Partial<LivingTypeMaterial>;
  className?: string;
  style?: CSSProperties;
  /** Optional observation hook for a demo or analytics wrapper. */
  onRendererStateChange?: (state: LivingTypeRendererState) => void;
}

export type LivingTypeRendererState =
  | "loading"
  | "shader"
  | "static-fallback"
  | "context-lost"
  | "mask-error"
  | "mask-unsupported"
  | "shader-error";
type RendererState = LivingTypeRendererState;


function combineClassNames(...values: (string | undefined)[]): string {
  return values.filter(Boolean).join(" ");
}

function usePrefersReducedMotion(): boolean {
  const [prefers, setPrefers] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setPrefers(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return prefers;
}

function recipeFromProps(props: LivingTypeProps): LivingTypeRecipe {
  const options: LivingTypeRecipeOptions = {
    text: props.text,
    preset: props.preset,
    paused: props.paused,
    reducedMotion: props.reducedMotion,
    weight: props.weight,
    fit: props.fit,
    tracking: props.tracking,
    aspect: props.aspect,
    colors: props.colors,
    material: props.material,
  };
  const clean = Object.fromEntries(
    Object.entries(options).filter(([, value]) => value !== undefined),
  ) as LivingTypeRecipeOptions;
  return createLivingTypeRecipe(clean);
}

function RecipeError({ issues }: { issues: { path: string; message: string }[] }) {
  const visible = issues.slice(0, 6);
  return (
    <div className={styles.recipeError} role="alert" data-living-type-error="true">
      <p className={styles.recipeErrorTitle}>Living Type 01 rejected this recipe.</p>
      <ul className={styles.recipeErrorList}>
        {visible.map((issue) => (
          <li key={`${issue.path}:${issue.message}`}>
            <code>{issue.path}</code> {issue.message}
          </li>
        ))}
      </ul>
      {issues.length > visible.length ? (
        <p className={styles.recipeErrorMore}>and {issues.length - visible.length} more issue(s).</p>
      ) : null}
    </div>
  );
}

class ShaderErrorBoundary extends Component<
  { onFailure: () => void; children: ReactNode },
  { failed: boolean }
> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch() {
    this.props.onFailure();
  }

  render() {
    return this.state.failed ? null : this.props.children;
  }
}

function rendererFor(
  webgl: string,
  maskStatus: string,
  maskSupport: "checking" | "supported" | "unsupported",
): RendererState {
  if (maskSupport === "unsupported") return "mask-unsupported";
  if (maskStatus === "error") return "mask-error";
  if (webgl === "unsupported") return "static-fallback";
  if (webgl === "lost") return "context-lost";
  if (webgl === "failed") return "shader-error";
  if (webgl === "ready" && maskStatus === "ready") return "shader";
  return "loading";
}

function fallbackMessage(renderer: RendererState, maskError: string | null): string {
  if (renderer === "context-lost") return "WebGL context lost · static fallback";
  if (renderer === "shader-error") return "Renderer failed · static fallback";
  if (renderer === "mask-error") return maskError ?? "Typesetting failed · static fallback";
  if (renderer === "mask-unsupported") return "CSS mask unavailable · static fallback";
  return "WebGL2 unavailable · static fallback";
}

function LivingTypeRenderer({
  recipe,
  paused,
  reducedMotion,
  className,
  style,
  onRendererStateChange,
}: {
  recipe: LivingTypeRecipe;
  paused?: boolean;
  reducedMotion?: ReducedMotionPreference;
  className?: string;
  style?: CSSProperties;
  onRendererStateChange?: (state: LivingTypeRendererState) => void;
}) {
  const config = recipe.config;
  const [webgl, setWebgl] = useState<"checking" | "ready" | "unsupported" | "lost" | "failed">(
    "checking",
  );
  const [retryNonce, setRetryNonce] = useState(0);
  const [maskSupport, setMaskSupport] = useState<"checking" | "supported" | "unsupported">("checking");
  const prefersReduced = usePrefersReducedMotion();
  const font = useLivingTypeFont(config.font.weight);
  const { rootRef, box, mask, maskKey } = useLivingTypeMask({
    text: config.text,
    weight: config.font.weight,
    fit: config.font.fit,
    tracking: config.font.tracking,
    aspect: config.layout.aspect,
    fontStatus: font.status,
  });

  const effectivePaused = paused ?? config.playback.paused;
  const reduced =
    (reducedMotion ?? config.playback.reducedMotion) === "force" ||
    ((reducedMotion ?? config.playback.reducedMotion) === "auto" && prefersReduced);
  const motionPaused = effectivePaused || reduced;
  const renderer = rendererFor(webgl, mask.status, maskSupport);

  useEffect(() => {
    if (typeof CSS === "undefined" || typeof CSS.supports !== "function") {
      setMaskSupport("unsupported");
      return;
    }
    const supported =
      CSS.supports("mask-image", "linear-gradient(#000, #000)") ||
      CSS.supports("-webkit-mask-image", "linear-gradient(#000, #000)");
    setMaskSupport(supported ? "supported" : "unsupported");
  }, []);

  useEffect(() => {
    onRendererStateChange?.(renderer);
  }, [onRendererStateChange, renderer]);

  useEffect(() => {
    setWebgl("checking");
    let disposed = false;
    try {
      const probe = document.createElement("canvas");
      const context = probe.getContext("webgl2", {
        alpha: true,
        antialias: false,
        powerPreference: "high-performance",
      });
      if (!context) {
        setWebgl("unsupported");
        return;
      }
      context.getExtension("WEBGL_lose_context")?.loseContext();
      if (!disposed) setWebgl("ready");
      return () => {
        disposed = true;
      };
    } catch {
      setWebgl("unsupported");
    }
    return () => {
      disposed = true;
    };
  }, [retryNonce]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const onLost = (event: Event) => {
      // Keep the event cancelable so the browser may restore the context while
      // we deliberately unmount the broken mount and show a static fallback.
      event.preventDefault();
      setWebgl("lost");
    };
    root.addEventListener("webglcontextlost", onLost, true);
    return () => root.removeEventListener("webglcontextlost", onLost, true);
  }, [rootRef]);

  const shaderProps = useMemo<MeshGradientProps>(
    () => ({
      colors: config.colors,
      speed: motionPaused ? 0 : config.material.speed,
      frame: 0,
      distortion: config.material.distortion,
      swirl: config.material.swirl,
      grainMixer: config.material.grainMixer,
      grainOverlay: config.material.grainOverlay,
      fit: "cover",
      scale: config.material.scale,
      rotation: config.material.rotation,
      minPixelRatio: 1,
      maxPixelCount: 1_500_000,
      style: { width: "100%", height: "100%" },
    }),
    [config.colors, config.material, motionPaused],
  );

  const fallbackFontSize =
    box.width > 0
      ? Math.max(
          10,
          Math.min(
            (box.width * 0.86) /
              Math.max(
                1,
                config.text.length * 0.82 +
                  Math.max(0, config.font.tracking) * Math.max(0, config.text.length - 1),
              ),
            box.height * 0.56,
          ),
        )
      : undefined;

  const stylesheet = {
    ...style,
    aspectRatio: String(config.layout.aspect),
    "--lt-glow-rgb": hexToRgbTriplet(config.colors[1]),
    "--lt-glow-alt-rgb": hexToRgbTriplet(config.colors[3]),
    "--lt-weight": String(config.font.weight),
    "--lt-tracking": `${config.font.tracking}em`,
    "--lt-fallback-size": fallbackFontSize ? `${fallbackFontSize}px` : undefined,
  } as CSSProperties;

  const showFallback =
    renderer === "static-fallback" ||
    renderer === "context-lost" ||
    renderer === "shader-error" ||
    renderer === "mask-error" ||
    renderer === "mask-unsupported";
  const canRetry = renderer === "context-lost" || renderer === "shader-error";
  const maskReady = mask.status === "ready";
  const maskError = mask.status === "error" ? mask.message : null;
  const maskStyle: CSSProperties | undefined = maskReady
    ? {
        maskImage: `url("${mask.url}")`,
        WebkitMaskImage: `url("${mask.url}")`,
      }
    : undefined;

  return (
    <div
      ref={rootRef}
      className={combineClassNames(styles.root, className)}
      style={stylesheet}
      data-living-type="living-type-01"
      data-preset={config.preset}
      data-renderer={renderer}
      data-webgl={webgl}
      data-mask-state={mask.status}
      data-mask-support={maskSupport}
      data-mask-key={maskKey}
      data-mask-engine={maskReady ? mask.engine : undefined}
      data-mask-width={maskReady ? mask.width : undefined}
      data-mask-height={maskReady ? mask.height : undefined}
      data-font-state={font.status}
      data-paused={motionPaused ? "true" : "false"}
      data-reduced={reduced ? "true" : "false"}
      data-text={config.text}
      aria-busy={mask.status === "pending" ? "true" : "false"}
    >
      <span className={styles.srOnly}>{config.text}</span>

      <div className={styles.visual} aria-hidden="true">
        <div className={styles.halo} />
        <div
          className={styles.maskLayer}
          data-ready={maskReady ? "true" : "false"}
          style={maskStyle}
        >
          {webgl === "ready" && maskSupport === "supported" && mask.status !== "error" ? (
            <ShaderErrorBoundary onFailure={() => setWebgl("failed")}>
              <Suspense fallback={null}>
                <LazyMeshGradient {...shaderProps} />
              </Suspense>
            </ShaderErrorBoundary>
          ) : null}
        </div>

        {showFallback ? (
          <div className={styles.fallback} data-testid="living-type-fallback">
            <span className={styles.fallbackText}>{config.text}</span>
            <span className={styles.fallbackNote}>{fallbackMessage(renderer, maskError)}</span>
          </div>
        ) : null}
      </div>

      {canRetry ? (
        <button
          type="button"
          className={styles.retry}
          onClick={() => {
            setWebgl("checking");
            setRetryNonce((value) => value + 1);
          }}
        >
          Retry renderer
        </button>
      ) : null}

      <span className={styles.srOnly} role="status">
        {mask.status === "pending"
          ? "Setting the wordmark."
          : renderer === "shader"
            ? "Wordmark ready."
            : showFallback
              ? fallbackMessage(renderer, maskError)
              : ""}
      </span>
    </div>
  );
}

/**
 * NULLWORX / LIVING TYPE 01.
 *
 * The accessible wordmark is real DOM text. All canvas and shader output is
 * decorative and hidden from assistive technology, so the word is announced
 * once, not once per visual layer.
 */
export function LivingType({
  recipe,
  text,
  preset,
  paused,
  reducedMotion,
  weight,
  fit,
  tracking,
  aspect,
  colors,
  material,
  className,
  style,
  onRendererStateChange,
}: LivingTypeProps) {
  const parsed = useMemo(() => {
    if (recipe) return parseLivingTypeRecipe(recipe);
    try {
      return parseLivingTypeRecipe(
        recipeFromProps({
          text,
          preset,
          paused,
          reducedMotion,
          weight,
          fit,
          tracking,
          aspect,
          colors,
          material,
        }),
      );
    } catch (error) {
      return {
        ok: false as const,
        issues: [{ path: "(props)", message: error instanceof Error ? error.message : String(error) }],
      };
    }
  }, [recipe, text, preset, paused, reducedMotion, weight, fit, tracking, aspect, colors, material]);

  if (!parsed.ok) return <RecipeError issues={parsed.issues} />;

  return (
    <LivingTypeRenderer
      recipe={parsed.recipe}
      paused={paused}
      reducedMotion={reducedMotion}
      className={className}
      style={style}
      onRendererStateChange={onRendererStateChange}
    />
  );
}

export { DEFAULT_LIVING_TYPE_RECIPE, DEFAULT_PRESET_ID, LIVING_TYPE_TEXT_PATTERN };
export {
  LIVING_TYPE_PRESETS,
  PRESET_IDS,
  createLivingTypeRecipe,
  getPreset,
  parseLivingTypeRecipe,
  stringifyLivingTypeRecipe,
  updateLivingTypeRecipe,
} from "./living-type-recipe";
export type { FontStatus } from "./living-type-mask";
export type {
  LivingTypeColors,
  LivingTypeMaterial,
  LivingTypePresetId,
  LivingTypeRecipe,
  LivingTypeRecipeOptions,
  ReducedMotionPreference,
  RecipeIssue,
  RecipeParseResult,
} from "./living-type-recipe";

/* NULLWORX / LIVING TYPE 01 — scoped visual system. No global reset. */

.root {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  isolation: isolate;
  container-type: inline-size;
  background: var(--lt-bg);
  color: var(--lt-ink);
  font-family: "Unbounded Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}

.root,
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  box-shadow: inset 0 0 min(13vw, 170px) var(--lt-vignette);
}

.root[data-preset="night-bloom"] {
  --lt-bg:
    radial-gradient(ellipse 76% 120% at 50% -18%, #1d1238 0%, transparent 62%),
    #07050d;
  --lt-ink: #f5f3ff;
  --lt-muted: #a8a0c0;
  --lt-halo-opacity: 0.5;
  --lt-vignette: rgb(0 0 0 / 0.42);
  --lt-fallback-ink: #efe7ff;
  --lt-fallback-shadow: 0 0 4.5cqi rgb(124 58 237 / 0.55);
  --lt-focus: #e9d5ff;
  --lt-sheen-light: 0.24;
  --lt-sheen-dark: 0.2;
  --lt-sheen-angle: 108deg;
}

.root[data-preset="kiln"] {
  --lt-bg:
    radial-gradient(ellipse 90% 120% at 14% 0%, #fff8ed 0%, transparent 58%),
    linear-gradient(128deg, #f5ead9 0%, #e9dac4 100%);
  --lt-ink: #3d1b10;
  --lt-muted: #805d4d;
  --lt-halo-opacity: 0.36;
  --lt-vignette: rgb(82 36 18 / 0.2);
  --lt-fallback-ink: #4a2012;
  --lt-fallback-shadow: 0 0 3.5cqi rgb(194 65 12 / 0.22);
  --lt-focus: #7c2d12;
  --lt-sheen-light: 0.34;
  --lt-sheen-dark: 0.14;
  --lt-sheen-angle: 98deg;
}

.root[data-preset="low-tide"] {
  --lt-bg:
    radial-gradient(ellipse 100% 130% at 82% -20%, #f8fffd 0%, transparent 55%),
    linear-gradient(172deg, #edf7f3 0%, #dcebe6 100%);
  --lt-ink: #073b36;
  --lt-muted: #4f756e;
  --lt-halo-opacity: 0.34;
  --lt-vignette: rgb(15 63 58 / 0.18);
  --lt-fallback-ink: #073b36;
  --lt-fallback-shadow: 0 0 3.5cqi rgb(15 118 110 / 0.18);
  --lt-focus: #0f766e;
  --lt-sheen-light: 0.26;
  --lt-sheen-dark: 0.1;
  --lt-sheen-angle: 122deg;
}

.visual {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.halo {
  position: absolute;
  inset: -12%;
  z-index: 0;
  opacity: var(--lt-halo-opacity);
  background:
    radial-gradient(
      ellipse 48% 76% at 50% 52%,
      rgb(var(--lt-glow-rgb) / 0.55) 0%,
      rgb(var(--lt-glow-rgb) / 0.16) 38%,
      transparent 72%
    ),
    radial-gradient(
      ellipse 58% 46% at 70% 48%,
      rgb(var(--lt-glow-alt-rgb) / 0.3) 0%,
      transparent 72%
    );
  filter: blur(18px);
}

.maskLayer {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0;
  pointer-events: none;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-mode: alpha;
  mask-mode: alpha;
}

.maskLayer[data-ready="true"] {
  opacity: 1;
}

.maskLayer::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(
      var(--lt-sheen-angle, 108deg),
      rgb(255 255 255 / var(--lt-sheen-light, 0.22)) 0%,
      transparent 35%,
      rgb(0 0 0 / var(--lt-sheen-dark, 0.16)) 76%,
      rgb(255 255 255 / calc(var(--lt-sheen-light, 0.22) * 0.35)) 100%
    );
  mix-blend-mode: soft-light;
  pointer-events: none;
}

.fallback {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 3cqi;
  color: var(--lt-fallback-ink);
  text-align: center;
}

.fallbackText {
  display: block;
  max-width: 100%;
  overflow: hidden;
  font-size: var(--lt-fallback-size, clamp(1.1rem, 6cqi, 4rem));
  font-weight: var(--lt-weight, 700);
  line-height: 1;
  letter-spacing: var(--lt-tracking, 0em);
  white-space: nowrap;
  text-shadow: var(--lt-fallback-shadow);
}

.fallbackNote {
  position: absolute;
  left: 3.4%;
  bottom: 4.5%;
  max-width: 60%;
  color: var(--lt-muted);
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: clamp(6px, 0.88cqi, 9px);
  line-height: 1.5;
  letter-spacing: 0.12em;
  text-align: left;
  text-transform: uppercase;
}

.retry {
  position: absolute;
  right: 3.4%;
  bottom: 4.2%;
  z-index: 6;
  padding: 0.5em 0.75em;
  border: 1px solid rgb(255 255 255 / 0.38);
  border-radius: 3px;
  background: rgb(0 0 0 / 0.55);
  color: #fff;
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: clamp(7px, 0.92cqi, 10px);
  line-height: 1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}

.retry:hover {
  background: rgb(0 0 0 / 0.72);
}

.retry:focus-visible {
  outline: 2px solid var(--lt-focus);
  outline-offset: 3px;
}

.srOnly {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.recipeError {
  display: grid;
  gap: 0.55rem;
  max-width: 62rem;
  padding: 1rem 1.1rem;
  border: 1px solid #c2410c;
  border-radius: 4px;
  background: #1d0d08;
  color: #ffd9c7;
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 0.78rem;
  line-height: 1.55;
}

.recipeErrorTitle {
  margin: 0;
  font-weight: 600;
}

.recipeErrorList {
  display: grid;
  gap: 0.25rem;
  margin: 0;
  padding-left: 1.1rem;
}

.recipeErrorList code {
  color: #ffb27e;
}

.recipeErrorMore {
  margin: 0;
  color: #d8a48d;
}

@media (prefers-reduced-motion: reduce) {
  .retry {
    transition: none;
  }
}

/* Unbounded Variable 5.3.0 — ASCII subset, OFL-1.1.
 * Source: @fontsource-variable/unbounded@5.3.0, unbounded-latin-wght-normal.woff2
 * Original SHA-256: 22f9b928aa3928a896340422b54d690fbb5875c30eae4c106f029c61f2289fd6
 * Subset SHA-256: 3e99d2422c4a5c962cbd13889295e0d7d5273c844aeff1a2b35f9c54c4721d2b
 * Embedded because shadcn registry items transport text files, not binary assets.
 * The full OFL text is installed beside this file as UNBOUNDED_OFL.txt.
 */
@font-face {
  font-family: "Unbounded Variable";
  font-style: normal;
  font-display: swap;
  font-weight: 200 900;
  unicode-range: U+0020-007E;
  src: url("data:font/woff2;base64,") format("woff2-variations");
}

/**
 * NULLWORX / LIVING TYPE 01 — recipe contract.
 *
 * This file is dependency-free so it can validate recipes on the server, in a
 * build script, or in a consumer test without mounting the shader.
 */

export const LIVING_TYPE_SCHEMA_VERSION = "1.0.0" as const;
export const LIVING_TYPE_EFFECT_ID = "living-type-01" as const;
export const LIVING_TYPE_EFFECT_VERSION = "1.0.0" as const;
export const LIVING_TYPE_FONT_FAMILY = "Unbounded Variable" as const;
export const LIVING_TYPE_FONT_VERSION = "5.3.0" as const;
export const LIVING_TYPE_TEXT_MAX = 24;
export const LIVING_TYPE_TEXT_PATTERN = /^[A-Za-z0-9][A-Za-z0-9 .&'!?+\-/]*$/;
export const LIVING_TYPE_SUPPORTED_CHARACTERS =
  "A–Z, a–z, 0–9, space, . & ' ! ? + - /";

export const PRESET_IDS = ["night-bloom", "kiln", "low-tide"] as const;
export type LivingTypePresetId = (typeof PRESET_IDS)[number];

export type ReducedMotionPreference = "auto" | "force";

export type LivingTypeColors = [string, string, string, string];

export interface LivingTypeFont {
  family: typeof LIVING_TYPE_FONT_FAMILY;
  version: typeof LIVING_TYPE_FONT_VERSION;
  weight: number;
  fit: number;
