export const DEFAULT_PRESET_ID: LivingTypePresetId = "night-bloom";

export function getPreset(id: LivingTypePresetId): LivingTypePreset {
  const preset = LIVING_TYPE_PRESETS.find((entry) => entry.id === id);
  if (!preset) throw new Error(`Unknown Living Type preset: ${id}`);
  return preset;
}

function cloneConfig(config: LivingTypeConfig): LivingTypeConfig {
  return {
    ...config,
    font: { ...config.font },
    layout: { ...config.layout },
    colors: [...config.colors] as LivingTypeColors,
    material: { ...config.material },
    playback: { ...config.playback },
  };
}

export interface LivingTypeRecipeOptions {
  id?: string;
  version?: string;
  title?: string;
  preset?: LivingTypePresetId;
  text?: string;
  paused?: boolean;
  reducedMotion?: ReducedMotionPreference;
  weight?: number;
  fit?: number;
  tracking?: number;
  aspect?: number;
  colors?: LivingTypeColors;
  material?: Partial<LivingTypeMaterial>;
}

/**
 * Build a complete, self-contained recipe. Presets only supply defaults: the
 * stored colours, type metrics and material values are always explicit so a
 * saved recipe does not drift when preset defaults change.
 */
export function createLivingTypeRecipe(options: LivingTypeRecipeOptions = {}): LivingTypeRecipe {
  const preset = getPreset(options.preset ?? DEFAULT_PRESET_ID);
  const config = cloneConfig(preset.config);
  if (options.text !== undefined) config.text = options.text;
  if (options.paused !== undefined) config.playback.paused = options.paused;
  if (options.reducedMotion !== undefined) config.playback.reducedMotion = options.reducedMotion;
  if (options.weight !== undefined) config.font.weight = options.weight;
  if (options.fit !== undefined) config.font.fit = options.fit;
  if (options.tracking !== undefined) config.font.tracking = options.tracking;
  if (options.aspect !== undefined) config.layout.aspect = options.aspect;
  if (options.colors !== undefined) config.colors = [...options.colors] as LivingTypeColors;
  if (options.material !== undefined) config.material = { ...config.material, ...options.material };

  const recipe: LivingTypeRecipe = {
    schemaVersion: LIVING_TYPE_SCHEMA_VERSION,
    effect: { id: LIVING_TYPE_EFFECT_ID, version: LIVING_TYPE_EFFECT_VERSION },
    id: options.id ?? "nullworx-living-type-01",
    version: options.version ?? "1.0.0",
    title: options.title ?? `${config.text} / ${preset.name}`,
    config,
  };
  const parsed = parseLivingTypeRecipe(recipe);
  if (!parsed.ok) {
    throw new Error(
      `Invalid Living Type recipe: ${parsed.issues.map((issue) => `${issue.path}: ${issue.message}`).join("; ")}`,
    );
  }
  return parsed.recipe;
}

/**
 * Update an existing recipe while preserving its id, version and title.
 * Changing the preset intentionally resets the preset-owned visual defaults
 * while preserving the wordmark, title and playback choices.
 */
export function updateLivingTypeRecipe(
  recipe: LivingTypeRecipe,
  patch: LivingTypeRecipeOptions,
): LivingTypeRecipe {
  const presetChanged = patch.preset !== undefined && patch.preset !== recipe.config.preset;
  return createLivingTypeRecipe({
    id: patch.id ?? recipe.id,
    version: patch.version ?? recipe.version,
    title: patch.title ?? recipe.title,
    preset: patch.preset ?? recipe.config.preset,
    text: patch.text ?? recipe.config.text,
    paused: patch.paused ?? recipe.config.playback.paused,
    reducedMotion: patch.reducedMotion ?? recipe.config.playback.reducedMotion,
    ...(presetChanged
      ? {}
      : {
          weight: patch.weight ?? recipe.config.font.weight,
          fit: patch.fit ?? recipe.config.font.fit,
          tracking: patch.tracking ?? recipe.config.font.tracking,
          aspect: patch.aspect ?? recipe.config.layout.aspect,
          colors: patch.colors ?? recipe.config.colors,
          material: { ...recipe.config.material, ...patch.material },
        }),
  });
}

const RECIPE_KEYS = new Set([
  "$schema",
  "schemaVersion",
  "effect",
  "id",
  "version",
  "title",
  "config",
]);
const CONFIG_KEYS = new Set([
  "text",
  "preset",
  "font",
  "layout",
  "colors",
  "material",
  "playback",
]);
const FONT_KEYS = new Set(["family", "version", "weight", "fit", "tracking"]);
const LAYOUT_KEYS = new Set(["aspect"]);
const MATERIAL_KEYS = new Set([
  "speed",
  "distortion",
  "swirl",
  "grainMixer",
  "grainOverlay",
  "scale",
  "rotation",
]);
const PLAYBACK_KEYS = new Set(["paused", "reducedMotion"]);

export const DEFAULT_LIVING_TYPE_RECIPE = createLivingTypeRecipe({
  id: "nullworx-living-type-01",
  title: "NULLWORX / Night Bloom",
});

export const RECIPE_EXAMPLE = DEFAULT_LIVING_TYPE_RECIPE;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function rejectUnknown(
  value: Record<string, unknown>,
  allowed: Set<string>,
  path: string,
  issues: RecipeIssue[],
): void {
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      issues.push({ path: path ? `${path}.${key}` : key, message: "unknown field" });
    }
  }
}

function readString(
  value: unknown,
  path: string,
  issues: RecipeIssue[],
  limits: { min?: number; max: number; pattern?: RegExp; label: string },
): string | null {
  if (typeof value !== "string") {
    issues.push({ path, message: `expected ${limits.label}` });
    return null;
  }
  if (value.length < (limits.min ?? 1) || value.length > limits.max) {
    issues.push({
      path,
      message: `expected ${limits.label} between ${limits.min ?? 1} and ${limits.max} characters`,
    });
    return null;
  }
  if (limits.pattern && !limits.pattern.test(value)) {
    issues.push({ path, message: `expected ${limits.label}` });
    return null;
  }
  if (/[\u0000-\u001f\u007f]/.test(value)) {
    issues.push({ path, message: "control characters are not allowed" });
    return null;
  }
  return value;
}

function readNumber(
  value: unknown,
  path: string,
  issues: RecipeIssue[],
  limits: { min: number; max: number; integer?: boolean; step?: number; label: string },
): number | null {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    issues.push({ path, message: `expected ${limits.label}` });
    return null;
  }
  if (value < limits.min || value > limits.max) {
    issues.push({
      path,
      message: `${limits.label} must be between ${limits.min} and ${limits.max}`,
    });
    return null;
  }
  if (limits.integer && !Number.isInteger(value)) {
    issues.push({ path, message: `${limits.label} must be an integer` });
    return null;
  }
  if (limits.step && Math.abs(value / limits.step - Math.round(value / limits.step)) > 1e-9) {
    issues.push({ path, message: `${limits.label} must use steps of ${limits.step}` });
    return null;
  }
  return value;
}

function readBoolean(value: unknown, path: string, issues: RecipeIssue[]): boolean | null {
  if (typeof value !== "boolean") {
    issues.push({ path, message: "expected a boolean" });
    return null;
  }
  return value;
}

function readHex(value: unknown, path: string, issues: RecipeIssue[]): string | null {
  if (typeof value !== "string" || !/^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(value)) {
    issues.push({ path, message: "expected a #RGB or #RRGGBB colour" });
    return null;
  }
  return value;
}

function parseColors(value: unknown, path: string, issues: RecipeIssue[]): LivingTypeColors | null {
  if (!Array.isArray(value) || value.length !== 4) {
    issues.push({ path, message: "expected exactly four colours" });
    return null;
  }
  const colors = value.map((entry, index) => readHex(entry, `${path}.${index}`, issues));
  if (colors.some((entry) => entry === null)) return null;
  return colors as LivingTypeColors;
}

/**
 * Strict, non-coercing validation. Unknown fields are rejected so a recipe can
 * never smuggle arbitrary CSS, markup or executable configuration into the
 * component. The returned recipe is rebuilt from validated primitives.
 */
export function parseLivingTypeRecipe(input: unknown): RecipeParseResult {
  const issues: RecipeIssue[] = [];
  let value: unknown = input;

  if (typeof input === "string") {
    try {
      value = JSON.parse(input) as unknown;
    } catch {
      return { ok: false, issues: [{ path: "(root)", message: "recipe is not valid JSON" }] };
    }
  }

  if (!isRecord(value)) {
    return { ok: false, issues: [{ path: "(root)", message: "recipe must be an object" }] };
  }

  rejectUnknown(value, RECIPE_KEYS, "", issues);

  if (value.$schema !== undefined) {
    readString(value.$schema, "$schema", issues, { max: 300, label: "a schema path" });
  }

  if (value.schemaVersion !== LIVING_TYPE_SCHEMA_VERSION) {
    issues.push({
      path: "schemaVersion",
      message: `unsupported schema version ${JSON.stringify(value.schemaVersion)}; this build supports ${LIVING_TYPE_SCHEMA_VERSION}`,
    });
  }

  const effect = isRecord(value.effect) ? value.effect : null;
  if (!effect) {
    issues.push({ path: "effect", message: "expected an effect object" });
  } else {
    rejectUnknown(effect, new Set(["id", "version"]), "effect", issues);
    if (effect.id !== LIVING_TYPE_EFFECT_ID) {
      issues.push({
        path: "effect.id",
        message: `expected "${LIVING_TYPE_EFFECT_ID}", received ${JSON.stringify(effect.id)}`,
      });
    }
    if (effect.version !== LIVING_TYPE_EFFECT_VERSION) {
      issues.push({
        path: "effect.version",
        message: `recipe targets effect ${JSON.stringify(effect.version)}; this build is ${LIVING_TYPE_EFFECT_VERSION}`,
      });
    }
  }

  const id = readString(value.id, "id", issues, {
    max: 64,
    pattern: /^[a-z0-9]+(?:-[a-z0-9]+)*$/,
    label: "a kebab-case recipe id",
  });
  const version = readString(value.version, "version", issues, {
    max: 20,
    pattern: /^\d+\.\d+\.\d+$/,
    label: "a semver recipe version",
  });
  const title = readString(value.title, "title", issues, { max: 80, label: "a title" });

  const configValue = isRecord(value.config) ? value.config : null;
  let config: LivingTypeConfig | null = null;

  if (!configValue) {
    issues.push({ path: "config", message: "expected a config object" });
  } else {
    rejectUnknown(configValue, CONFIG_KEYS, "config", issues);

    const text = readString(configValue.text, "config.text", issues, {
      min: 1,
      max: LIVING_TYPE_TEXT_MAX,
      pattern: LIVING_TYPE_TEXT_PATTERN,
      label: `a single-line wordmark using ${LIVING_TYPE_SUPPORTED_CHARACTERS}`,
    });
    if (text && text.trim() !== text) {
      issues.push({
        path: "config.text",
        message: "leading or trailing spaces are not allowed",
      });
    }
    const preset =
      typeof configValue.preset === "string" &&
      (PRESET_IDS as readonly string[]).includes(configValue.preset)
        ? (configValue.preset as LivingTypePresetId)
        : null;
    if (!preset) {
      issues.push({
        path: "config.preset",
        message: `expected one of ${PRESET_IDS.join(", ")}`,
      });
    }

    const fontValue = isRecord(configValue.font) ? configValue.font : null;
    let font: LivingTypeFont | null = null;
    if (!fontValue) {
      issues.push({ path: "config.font", message: "expected a font object" });
    } else {
      rejectUnknown(fontValue, FONT_KEYS, "config.font", issues);
      if (fontValue.family !== LIVING_TYPE_FONT_FAMILY) {
        issues.push({
          path: "config.font.family",
          message: `expected "${LIVING_TYPE_FONT_FAMILY}"; custom families are not supported by this build`,
        });
      }
      if (fontValue.version !== LIVING_TYPE_FONT_VERSION) {
        issues.push({
          path: "config.font.version",
          message: `recipe targets font ${JSON.stringify(fontValue.version)}; this build is ${LIVING_TYPE_FONT_VERSION}`,
        });
      }
      const weight = readNumber(fontValue.weight, "config.font.weight", issues, {
        min: 200,
        max: 900,
        integer: true,
        step: 100,
        label: "font weight",
      });
      const fit = readNumber(fontValue.fit, "config.font.fit", issues, {
        min: 0.55,
        max: 0.94,
        label: "fit",
      });
      const tracking = readNumber(fontValue.tracking, "config.font.tracking", issues, {
        min: -0.04,
        max: 0.14,
        label: "tracking",
      });
      if (
        fontValue.family === LIVING_TYPE_FONT_FAMILY &&
        fontValue.version === LIVING_TYPE_FONT_VERSION &&
        weight !== null &&
        fit !== null &&
        tracking !== null
      ) {
        font = { family: LIVING_TYPE_FONT_FAMILY, version: LIVING_TYPE_FONT_VERSION, weight, fit, tracking };
      }
    }

    const layoutValue = isRecord(configValue.layout) ? configValue.layout : null;
    let layout: LivingTypeLayout | null = null;
    if (!layoutValue) {
      issues.push({ path: "config.layout", message: "expected a layout object" });
    } else {
      rejectUnknown(layoutValue, LAYOUT_KEYS, "config.layout", issues);
      const aspect = readNumber(layoutValue.aspect, "config.layout.aspect", issues, {
        min: 2,
        max: 5,
        label: "aspect ratio",
      });
      if (aspect !== null) layout = { aspect };
    }

    const colors = parseColors(configValue.colors, "config.colors", issues);

    const materialValue = isRecord(configValue.material) ? configValue.material : null;
    let material: LivingTypeMaterial | null = null;
    if (!materialValue) {
      issues.push({ path: "config.material", message: "expected a material object" });
    } else {
      rejectUnknown(materialValue, MATERIAL_KEYS, "config.material", issues);
      const speed = readNumber(materialValue.speed, "config.material.speed", issues, {
        min: 0,
        max: 2,
        label: "speed",
      });
      const distortion = readNumber(
        materialValue.distortion,
        "config.material.distortion",
        issues,
        { min: 0, max: 2, label: "distortion" },
      );
      const swirl = readNumber(materialValue.swirl, "config.material.swirl", issues, {
        min: 0,
        max: 1.5,
        label: "swirl",
      });
      const grainMixer = readNumber(
        materialValue.grainMixer,
        "config.material.grainMixer",
        issues,
        { min: 0, max: 1, label: "grainMixer" },
      );
      const grainOverlay = readNumber(
        materialValue.grainOverlay,
        "config.material.grainOverlay",
        issues,
        { min: 0, max: 1, label: "grainOverlay" },
      );
      const scale = readNumber(materialValue.scale, "config.material.scale", issues, {
        min: 0.5,
        max: 2,
        label: "scale",
      });
      const rotation = readNumber(materialValue.rotation, "config.material.rotation", issues, {
        min: 0,
        max: 360,
        label: "rotation",
      });
      if (
        speed !== null &&
        distortion !== null &&
        swirl !== null &&
        grainMixer !== null &&
        grainOverlay !== null &&
        scale !== null &&
        rotation !== null
      ) {
        material = { speed, distortion, swirl, grainMixer, grainOverlay, scale, rotation };
      }
    }

    const playbackValue = isRecord(configValue.playback) ? configValue.playback : null;
    let playback: LivingTypePlayback | null = null;
    if (!playbackValue) {
      issues.push({ path: "config.playback", message: "expected a playback object" });
    } else {
      rejectUnknown(playbackValue, PLAYBACK_KEYS, "config.playback", issues);
      const paused = readBoolean(playbackValue.paused, "config.playback.paused", issues);
      const reducedMotion =
        playbackValue.reducedMotion === "auto" || playbackValue.reducedMotion === "force"
          ? playbackValue.reducedMotion
          : null;
      if (!reducedMotion) {
        issues.push({
          path: "config.playback.reducedMotion",
          message: 'expected "auto" or "force"',
        });
      }
      if (paused !== null && reducedMotion) playback = { paused, reducedMotion };
    }

    if (
      text &&
      preset &&
      font &&
      layout &&
      colors &&
      material &&
      playback
    ) {
      config = { text, preset, font, layout, colors, material, playback };
    }
  }

  if (issues.length > 0 || !config || !id || !version || !title) {
    return { ok: false, issues };
  }

  return {
    ok: true,
    recipe: {
      schemaVersion: LIVING_TYPE_SCHEMA_VERSION,
      effect: { id: LIVING_TYPE_EFFECT_ID, version: LIVING_TYPE_EFFECT_VERSION },
      id,
      version,
      title,
      config,
    },
  };
}

export function stringifyLivingTypeRecipe(input: unknown): string {
  const parsed = parseLivingTypeRecipe(input);
  if (!parsed.ok) {
    throw new Error(
      `Cannot serialise an invalid Living Type recipe: ${parsed.issues
        .map((issue) => `${issue.path}: ${issue.message}`)
        .join("; ")}`,
    );
  }
  return `${JSON.stringify(parsed.recipe, null, 2)}\n`;
}

/** Convert #RGB/#RRGGBB into a space-separated RGB triplet for CSS. */
export function hexToRgbTriplet(hex: string): string {
  if (!/^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(hex)) {
    throw new Error(`Unsafe colour: ${hex}`);
  }
  const value =
    hex.length === 4
      ? `${hex[1]}${hex[1]}${hex[2]}${hex[2]}${hex[3]}${hex[3]}`
      : hex.slice(1);
  return `${Number.parseInt(value.slice(0, 2), 16)} ${Number.parseInt(value.slice(2, 4), 16)} ${Number.parseInt(value.slice(4, 6), 16)}`;
}

"use client";

/**
 * Wordmark rasterization and cache identity for Living Type 01.
 *
 * The mask key is content-addressed. It includes the text, the pinned font
 * family/version, weight, fit, tracking, frame ratio, raster dimensions and
 * effective device pixel ratio. It never depends on a component id alone.
 */

import { useEffect, useMemo, useRef, useState, type RefObject } from "react";
import {
  LIVING_TYPE_FONT_FAMILY,
  LIVING_TYPE_FONT_VERSION,
} from "./living-type-recipe";

export const MASK_ALGORITHM_VERSION = "1";
export const FONT_PROBE = "Aa0";
export const FONT_TIMEOUT_MS = 1800;
export const MASK_DEBOUNCE_MS = 90;
export const MAX_RASTER_WIDTH = 4096;
export const MIN_RASTER_WIDTH = 160;

export type FontStatus = "loading" | "loaded" | "fallback";

export interface FontState {
  status: FontStatus;
  family: typeof LIVING_TYPE_FONT_FAMILY;
  version: typeof LIVING_TYPE_FONT_VERSION;
}

export interface MaskRequest {
  text: string;
  weight: number;
  fit: number;
  tracking: number;
  aspect: number;
  rasterWidth: number;
  rasterHeight: number;
  pixelRatio: number;
  fontStatus: Exclude<FontStatus, "loading">;
  fontFamily: typeof LIVING_TYPE_FONT_FAMILY;
  fontVersion: typeof LIVING_TYPE_FONT_VERSION;
}

export interface RasterizedMask {
  blob: Blob;
  width: number;
  height: number;
  fontStatus: Exclude<FontStatus, "loading">;
  engine: "canvas-letter-spacing" | "canvas-manual-tracking";
}

export type LivingTypeMaskState =
  | { status: "pending" }
  | {
      status: "ready";
      key: string;
      url: string;
      width: number;
      height: number;
      fontStatus: Exclude<FontStatus, "loading">;
      engine: RasterizedMask["engine"];
    }
  | { status: "error"; key: string; message: string };

const FALLBACK_STACK = "ui-sans-serif, system-ui, -apple-system, Segoe UI, sans-serif";
const MAX_RASTER_HEIGHT = 4096;

export function fontStack(fontStatus: FontStatus): string {
  return fontStatus === "loaded"
    ? `"${LIVING_TYPE_FONT_FAMILY}", ${FALLBACK_STACK}`
    : FALLBACK_STACK;
}

export function maskCacheKey(request: MaskRequest): string {
  return JSON.stringify([
    MASK_ALGORITHM_VERSION,
    request.text,
    request.fontFamily,
    request.fontVersion,
    request.weight,
    request.fit,
    request.tracking,
    request.aspect,
    request.rasterWidth,
    request.rasterHeight,
    request.pixelRatio,
    request.fontStatus,
  ]);
}

/** Stable short identifier for DOM receipts; not security-sensitive. */
export function shortHash(value: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function useLivingTypeFont(weight: number): FontState {
  const [state, setState] = useState<FontState>({
    status: "loading",
    family: LIVING_TYPE_FONT_FAMILY,
    version: LIVING_TYPE_FONT_VERSION,
  });
  const statusRef = useRef<FontStatus>("loading");

  useEffect(() => {
    let cancelled = false;
    statusRef.current = "loading";
    setState((previous) => ({ ...previous, status: "loading" }));

    if (typeof document === "undefined" || !document.fonts) {
      statusRef.current = "fallback";
      setState((previous) => ({ ...previous, status: "fallback" }));
      return;
    }

    const fontSet = document.fonts;
    const probe = `${weight} 100px "${LIVING_TYPE_FONT_FAMILY}"`;
    let timeout = 0;

    const update = (next: Exclude<FontStatus, "loading">) => {
      if (cancelled) return;
      // Never downgrade a loaded font because a later loading event failed.
      if (statusRef.current === "loaded" && next === "fallback") return;
      statusRef.current = next;
      setState((previous) =>
        previous.status === next ? previous : { ...previous, status: next },
      );
    };

    const detect = async () => {
      try {
        await fontSet.load(probe, FONT_PROBE);
      } catch {
        // A failed load means the declared fallback is used. Do not throw into
        // the render tree: the composition still has to be usable.
      }
      if (cancelled) return;
      let loaded = false;
      try {
        fontSet.forEach((face) => {
          const family = face.family.replace(/^['"]|['"]$/g, "");
          if (family === LIVING_TYPE_FONT_FAMILY && face.status === "loaded") {
            loaded = true;
          }
        });
      } catch {
        loaded = false;
      }
      update(loaded ? "loaded" : "fallback");
    };

    void detect();
    timeout = window.setTimeout(() => {
      if (statusRef.current === "loading") update("fallback");
    }, FONT_TIMEOUT_MS);

    const onLoadingDone = () => {
      // Upgrade fallback -> loaded if the font arrives late. Detect never
      // downgrades a loaded family.
      void detect();
    };
    fontSet.addEventListener("loadingdone", onLoadingDone);

    return () => {
      cancelled = true;
      window.clearTimeout(timeout);
      fontSet.removeEventListener("loadingdone", onLoadingDone);
    };
  }, [weight]);

  return state;
}

export interface StageBox {
  width: number;
  height: number;
  dpr: number;
}

function readStage(element: HTMLElement): StageBox {
  return {
    width: element.clientWidth,
    height: element.clientHeight,
    dpr: typeof window === "undefined" ? 1 : window.devicePixelRatio || 1,
  };
}

export interface UseLivingTypeMaskOptions {
  text: string;
  weight: number;
  fit: number;
  tracking: number;
  aspect: number;
  fontStatus: FontStatus;
}

export interface UseLivingTypeMaskResult {
  rootRef: RefObject<HTMLDivElement | null>;
  box: StageBox;
  request: MaskRequest | null;
  maskKey: string;
  mask: LivingTypeMaskState;
}

export function useLivingTypeMask({
  text,
  weight,
  fit,
  tracking,
  aspect,
  fontStatus,
}: UseLivingTypeMaskOptions): UseLivingTypeMaskResult {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [box, setBox] = useState<StageBox>({ width: 0, height: 0, dpr: 1 });
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const queueRef = useRef<Promise<unknown>>(Promise.resolve());
  const [entry, setEntry] = useState<{
    key: string;
    value: LivingTypeMaskState;
  } | null>(null);

  useEffect(() => {
    const element = rootRef.current;
    if (!element) return;

    let frame = 0;
    const measure = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const next = readStage(element);
        setBox((previous) =>
          previous.width === next.width &&
          previous.height === next.height &&
          previous.dpr === next.dpr
            ? previous
            : next,
        );
      });
    };

    measure();
    const observer =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener("resize", measure);
    window.visualViewport?.addEventListener("resize", measure);

    let resolutionQuery: MediaQueryList | null = null;
    const listenForResolution = () => {
      resolutionQuery?.removeEventListener("change", onResolutionChange);
      if (typeof window.matchMedia !== "function") return;
      resolutionQuery = window.matchMedia(
        `(resolution: ${window.devicePixelRatio || 1}dppx)`,
      );
      resolutionQuery.addEventListener("change", onResolutionChange);
    };
    const onResolutionChange = () => {
      measure();
      listenForResolution();
    };
    listenForResolution();

    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
      resolutionQuery?.removeEventListener("change", onResolutionChange);
      window.removeEventListener("resize", measure);
      window.visualViewport?.removeEventListener("resize", measure);
    };
  }, []);

  const request = useMemo<MaskRequest | null>(() => {
    if (box.width <= 0 || box.height <= 0 || fontStatus === "loading") return null;
    const pixelRatio = clamp(box.dpr || 1, 1, 2);
    const rasterWidth = clamp(
      Math.round(box.width * pixelRatio),
      MIN_RASTER_WIDTH,
      MAX_RASTER_WIDTH,
    );
    const rasterHeight = clamp(
      Math.round(rasterWidth / clamp(aspect, 2, 5)),
      1,
      MAX_RASTER_HEIGHT,
    );
    return {
      text,
      weight,
      fit,
      tracking,
      aspect,
      rasterWidth,
      rasterHeight,
      pixelRatio,
      fontStatus,
      fontFamily: LIVING_TYPE_FONT_FAMILY,
      fontVersion: LIVING_TYPE_FONT_VERSION,
    };
  }, [box, text, weight, fit, tracking, aspect, fontStatus]);

  const maskKey = request ? maskCacheKey(request) : `pending:${shortHash(`${text}|${weight}|${fit}|${tracking}|${aspect}|${fontStatus}`)}`;

  useEffect(() => {
    if (!request) return;
    const controller = new AbortController();
    let timer = 0;

    timer = window.setTimeout(() => {
      const task = queueRef.current.then(async () => {
        if (controller.signal.aborted) return;
        if (!canvasRef.current) {
          canvasRef.current = document.createElement("canvas");
        }
        const result = await rasterizeLivingTypeMask(request, canvasRef.current, controller.signal);
        if (controller.signal.aborted) return;
        const url = URL.createObjectURL(result.blob);
        if (controller.signal.aborted) {
          URL.revokeObjectURL(url);
          return;
        }
        setEntry({
          key: maskCacheKey(request),
          value: {
            status: "ready",
            key: maskCacheKey(request),
            url,
            width: result.width,
            height: result.height,
            fontStatus: result.fontStatus,
            engine: result.engine,
          },
        });
      });

      // Keep the queue alive after a rejected task.
      queueRef.current = task.catch(() => undefined);

      void task.catch((error: unknown) => {
        if (controller.signal.aborted) return;
        const message = error instanceof Error ? error.message : String(error);
        setEntry({
          key: maskCacheKey(request),
          value: { status: "error", key: maskCacheKey(request), message },
        });
      });
    }, MASK_DEBOUNCE_MS);

    return () => {
      window.clearTimeout(timer);
      controller.abort();
    };
  }, [request]);

  // Object URLs are revoked when the mask that owns them is replaced or the
  // component unmounts. The canvas itself is reused for the component's life.
  useEffect(() => {
    if (!entry || entry.value.status !== "ready") return;
    const url = entry.value.url;
    return () => URL.revokeObjectURL(url);
  }, [entry]);

  const derived: LivingTypeMaskState = useMemo(() => {
    if (!request) return { status: "pending" };
    if (entry && entry.key === maskKey) {
      if (entry.value.status === "ready" && entry.value.key === maskKey) return entry.value;
      if (entry.value.status === "error" && entry.value.key === maskKey) return entry.value;
    }
    return { status: "pending" };
  }, [entry, maskKey, request]);

  return { rootRef, box, request, maskKey: shortHash(maskKey), mask: derived };
}

function measureInk(
  context: CanvasRenderingContext2D,
): { left: number; right: number; top: number; bottom: number; width: number; height: number } {
  const metrics = context.measureText(context.canvas.dataset.livingText ?? "");
  const ascent = Number.isFinite(metrics.actualBoundingBoxAscent)
    ? metrics.actualBoundingBoxAscent
    : 0;
  const descent = Number.isFinite(metrics.actualBoundingBoxDescent)
    ? metrics.actualBoundingBoxDescent
    : 0;
  const actualLeft = Number.isFinite(metrics.actualBoundingBoxLeft)
    ? metrics.actualBoundingBoxLeft
    : 0;
  const actualRight = Number.isFinite(metrics.actualBoundingBoxRight)
    ? metrics.actualBoundingBoxRight
    : metrics.width;
  return {
    left: actualLeft,
    right: actualRight,
    top: ascent,
    bottom: descent,
    width: Math.max(actualLeft + actualRight, 1),
    height: Math.max(ascent + descent, 1),
  };
}

function setLetterSpacing(context: CanvasRenderingContext2D, size: number, tracking: number): boolean {
  const target = context as CanvasRenderingContext2D & { letterSpacing?: string };
  if (!("letterSpacing" in target)) return false;
  target.letterSpacing = `${tracking * size}px`;
  return true;
}

function drawWithLetterSpacing(
  context: CanvasRenderingContext2D,
  text: string,
  size: number,
  tracking: number,
  width: number,
  height: number,
): "canvas-letter-spacing" {
  context.font = `${context.canvas.dataset.livingWeight ?? "400"} ${size}px ${context.canvas.dataset.livingFont ?? FALLBACK_STACK}`;
  setLetterSpacing(context, size, tracking);
  const ink = measureInk(context);
  const x = width / 2 - (ink.right - ink.left) / 2;
  const baseline = height / 2 + (ink.top - ink.bottom) / 2;
  context.textAlign = "left";
  context.textBaseline = "alphabetic";
  context.fillStyle = "#fff";
  context.fillText(text, x, baseline);
  return "canvas-letter-spacing";
}

function drawWithManualTracking(
  context: CanvasRenderingContext2D,
  text: string,
  size: number,
  tracking: number,
  width: number,
  height: number,
): "canvas-manual-tracking" {
  context.font = `${context.canvas.dataset.livingWeight ?? "400"} ${size}px ${context.canvas.dataset.livingFont ?? FALLBACK_STACK}`;
  setLetterSpacing(context, 0, 0);
  const spacing = tracking * size;
  let pen = 0;
  let minX = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  const glyphs: { char: string; pen: number }[] = [];

  for (const char of text) {
    const metrics = context.measureText(char);
    const left = pen - metrics.actualBoundingBoxLeft;
    const right = pen + metrics.actualBoundingBoxRight;
    const top = -metrics.actualBoundingBoxAscent;
    const bottom = metrics.actualBoundingBoxDescent;
    if (char.trim().length > 0) {
      minX = Math.min(minX, left);
      maxX = Math.max(maxX, right);
      minY = Math.min(minY, top);
      maxY = Math.max(maxY, bottom);
    }
    glyphs.push({ char, pen });
    pen += metrics.width + spacing;
  }

  if (!Number.isFinite(minX)) {
    minX = 0;
    maxX = 1;
    minY = 0;
    maxY = 1;
  }

  const offsetX = width / 2 - (minX + maxX) / 2;
  const offsetY = height / 2 - (minY + maxY) / 2;
  context.textAlign = "left";
  context.textBaseline = "alphabetic";
  context.fillStyle = "#fff";
  for (const glyph of glyphs) {
    if (glyph.char.trim().length > 0) {
      context.fillText(glyph.char, offsetX + glyph.pen, offsetY);
    }
  }
  return "canvas-manual-tracking";
}

export async function rasterizeLivingTypeMask(
  request: MaskRequest,
  canvas: HTMLCanvasElement,
  signal: AbortSignal,
): Promise<RasterizedMask> {
  if (signal.aborted) throw new Error("Mask rasterisation cancelled.");
  if (typeof document === "undefined") {
    throw new Error("Text mask rasterisation requires a browser document.");
  }

  canvas.width = request.rasterWidth;
  canvas.height = request.rasterHeight;
  const context = canvas.getContext("2d", { alpha: true });
  if (!context) {
    throw new Error("Canvas 2D is unavailable; the wordmark mask cannot be rasterised.");
  }

  context.clearRect(0, 0, canvas.width, canvas.height);
  context.globalCompositeOperation = "source-over";
  context.fillStyle = "#fff";
  context.textAlign = "left";
  context.textBaseline = "alphabetic";

  const stack = fontStack(request.fontStatus);
  const weight = String(request.weight);
  canvas.dataset.livingText = request.text;
  canvas.dataset.livingWeight = weight;
  canvas.dataset.livingFont = stack;

  const targetWidth = request.rasterWidth * request.fit;
  const targetHeight = request.rasterHeight * 0.74;
  const supportsSpacing = "letterSpacing" in context;

  // Measure at a stable probe size, then scale once. The manual path repeats
  // measurement because per-character advances are not kerning-aware.
  context.font = `${weight} 100px ${stack}`;
  if (supportsSpacing) setLetterSpacing(context, 100, request.tracking);
  let probe = measureInk(context);
  let scale = Math.min(targetWidth / probe.width, targetHeight / probe.height);
  if (!Number.isFinite(scale) || scale <= 0) scale = 1;
  let size = 100 * scale;

  if (!supportsSpacing) {
    // Probe the manual layout at 100px to include tracking in the fit.
    const manual = context as CanvasRenderingContext2D;
    const spacing = request.tracking * 100;
    let pen = 0;
    let minX = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;
    let minY = Number.POSITIVE_INFINITY;
    let maxY = Number.NEGATIVE_INFINITY;
    for (const char of request.text) {
      const metrics = manual.measureText(char);
      if (char.trim().length > 0) {
        minX = Math.min(minX, pen - metrics.actualBoundingBoxLeft);
        maxX = Math.max(maxX, pen + metrics.actualBoundingBoxRight);
        minY = Math.min(minY, -metrics.actualBoundingBoxAscent);
        maxY = Math.max(maxY, metrics.actualBoundingBoxDescent);
      }
      pen += metrics.width + spacing;
    }
    if (Number.isFinite(minX) && Number.isFinite(maxX)) {
      probe = {
        left: minX,
        right: maxX,
        top: -minY,
        bottom: maxY,
        width: Math.max(maxX - minX, 1),
        height: Math.max(maxY - minY, 1),
      };
      scale = Math.min(targetWidth / probe.width, targetHeight / probe.height);
      if (!Number.isFinite(scale) || scale <= 0) scale = 1;
      size = 100 * scale;
    }
  }

  size = Math.max(1, size);
  context.font = `${weight} ${size}px ${stack}`;
  if (supportsSpacing) {
    setLetterSpacing(context, size, request.tracking);
    probe = measureInk(context);
    // Guard against non-linear metrics at the final size.
    if (probe.width > targetWidth || probe.height > targetHeight) {
      const correction = Math.min(targetWidth / probe.width, targetHeight / probe.height, 1) * 0.995;
      size *= correction;
      context.font = `${weight} ${size}px ${stack}`;
      setLetterSpacing(context, size, request.tracking);
    }
  }

  if (signal.aborted) throw new Error("Mask rasterisation cancelled.");

  const engine = supportsSpacing
    ? drawWithLetterSpacing(context, request.text, size, request.tracking, request.rasterWidth, request.rasterHeight)
    : drawWithManualTracking(context, request.text, size, request.tracking, request.rasterWidth, request.rasterHeight);

  if (signal.aborted) throw new Error("Mask rasterisation cancelled.");

  const blob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob((value) => {
      if (value) resolve(value);
      else reject(new Error("The wordmark mask could not be encoded as a PNG."));
    }, "image/png");
  });

  if (signal.aborted) throw new Error("Mask rasterisation cancelled.");

  return {
    blob,
    width: request.rasterWidth,
    height: request.rasterHeight,
    fontStatus: request.fontStatus,
    engine,
  };
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "living-type.recipe.schema.json",
  "title": "NULLWORX / Living Type 01 recipe",
  "description": "Validated configuration for one Living Type 01 wordmark composition. It does not contain a time value and cannot reproduce an animation frame-for-frame.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "effect", "id", "version", "title", "config"],
  "properties": {
    "$schema": {
      "type": "string",
      "maxLength": 300
    },
    "schemaVersion": {
      "const": "1.0.0"
    },
    "effect": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "version"],
      "properties": {
        "id": { "const": "living-type-01" },
        "version": { "const": "1.0.0" }
      }
    },
    "id": {
      "type": "string",
      "maxLength": 64,
      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$"
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$"
    },
    "title": {
      "type": "string",
      "minLength": 1,
      "maxLength": 80
    },
    "config": {
      "type": "object",
      "additionalProperties": false,
      "required": ["text", "preset", "font", "layout", "colors", "material", "playback"],
      "properties": {
        "text": {
          "type": "string",
          "minLength": 1,
          "maxLength": 24,
          "pattern": "^[A-Za-z0-9][A-Za-z0-9 .&'!?+\\-/]*$",
          "description": "One line, Latin A-Z/a-z, digits, space, and . & ' ! ? + - /. No Unicode or markup."
        },
        "preset": {
          "enum": ["night-bloom", "kiln", "low-tide"]
        },
        "font": {
          "type": "object",
          "additionalProperties": false,
          "required": ["family", "version", "weight", "fit", "tracking"],
          "properties": {
            "family": { "const": "Unbounded Variable" },
            "version": { "const": "5.3.0" },
            "weight": {
              "type": "integer",
              "minimum": 200,
              "maximum": 900,
              "multipleOf": 100
            },
            "fit": {
              "type": "number",
              "minimum": 0.55,
              "maximum": 0.94
            },
            "tracking": {
              "type": "number",
              "minimum": -0.04,
              "maximum": 0.14
            }
          }
        },
        "layout": {
          "type": "object",
          "additionalProperties": false,
          "required": ["aspect"],
          "properties": {
            "aspect": {
              "type": "number",
              "minimum": 2,
              "maximum": 5,
              "description": "Frame width divided by height."
            }
          }
        },
        "colors": {
          "type": "array",
          "minItems": 4,
          "maxItems": 4,
          "items": {
            "type": "string",
            "pattern": "^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$"
          }
        },
        "material": {
          "type": "object",
          "additionalProperties": false,
          "required": ["speed", "distortion", "swirl", "grainMixer", "grainOverlay", "scale", "rotation"],
          "properties": {
            "speed": { "type": "number", "minimum": 0, "maximum": 2 },
            "distortion": { "type": "number", "minimum": 0, "maximum": 2 },
            "swirl": { "type": "number", "minimum": 0, "maximum": 1.5 },
            "grainMixer": { "type": "number", "minimum": 0, "maximum": 1 },
            "grainOverlay": { "type": "number", "minimum": 0, "maximum": 1 },
            "scale": { "type": "number", "minimum": 0.5, "maximum": 2 },
            "rotation": { "type": "number", "minimum": 0, "maximum": 360 }
          }
        },
        "playback": {
          "type": "object",
          "additionalProperties": false,
          "required": ["paused", "reducedMotion"],
          "properties": {
            "paused": { "type": "boolean" },
            "reducedMotion": { "enum": ["auto", "force"] }
          }
        }
      }
    }
  }
}
